#!/usr/bin/env python3
"""Observation-only multi-project scheduler for the EDARSAHUB Universal Worker.

Shadow mode only:
- never moves queue files;
- never executes jobs;
- never acquires writer locks;
- never changes Git branches;
- only reads pending/processing envelopes and emits a deterministic decision.
"""
from __future__ import annotations

import json
import os
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable

ROOT = Path(os.environ.get("EDARSAHUB_ROOT", "/app"))
STATE = ROOT / ".git" / "universal-worker-queue"
PENDING = STATE / "pending"
PROCESSING = STATE / "processing"

PRIORITY_ORDER = {"P0": 0, "P1": 10, "HIGH": 20, "NORMAL": 50, "LOW": 80}
GLOBAL_CONFLICT_DOMAINS = {"CORE", "GLOBAL_GIT_WRITER", "GLOBAL_FRONTEND_REGISTRY", "GLOBAL_NAVIGATION"}


@dataclass(frozen=True)
class SchedulingMeta:
    project_id: str
    bounded_context: str
    resource_claims: tuple[str, ...]
    conflict_domains: tuple[str, ...]
    priority_class: str
    fairness_weight: int
    max_parallelism: int
    mode: str
    legacy_defaults: bool


def _norm(values: Iterable[Any]) -> tuple[str, ...]:
    return tuple(sorted({str(v).strip() for v in values if str(v).strip()}))


def _safe_int(value: Any, default: int, minimum: int = 1, maximum: int = 64) -> int:
    try:
        n = int(value)
    except (TypeError, ValueError):
        return default
    return max(minimum, min(maximum, n))


def normalize_metadata(job: dict[str, Any]) -> SchedulingMeta:
    sched = job.get("scheduling")
    legacy = not isinstance(sched, dict)
    sched = sched if isinstance(sched, dict) else {}

    # Legacy jobs are intentionally conservative: they share one global
    # conflict domain, so shadow mode will never claim they are safely parallel.
    project_id = str(sched.get("project_id") or ("LEGACY_GLOBAL" if legacy else "UNSPECIFIED")).strip()
    bounded_context = str(sched.get("bounded_context") or ("LEGACY_GLOBAL" if legacy else project_id)).strip()

    claims = _norm(sched.get("resource_claims") or ())
    domains = _norm(sched.get("conflict_domains") or ())
    if legacy:
        domains = ("GLOBAL_GIT_WRITER",)

    priority = str(sched.get("priority_class") or "NORMAL").upper().strip()
    if priority not in PRIORITY_ORDER:
        priority = "NORMAL"

    return SchedulingMeta(
        project_id=project_id,
        bounded_context=bounded_context,
        resource_claims=claims,
        conflict_domains=domains,
        priority_class=priority,
        fairness_weight=_safe_int(sched.get("fairness_weight"), 1),
        max_parallelism=_safe_int(sched.get("max_parallelism"), 1),
        mode=str(job.get("mode") or "").upper().strip(),
        legacy_defaults=legacy,
    )


def claims_conflict(a: SchedulingMeta, b: SchedulingMeta) -> bool:
    ad = set(a.conflict_domains)
    bd = set(b.conflict_domains)
    if ad & bd:
        return True
    if ad & GLOBAL_CONFLICT_DOMAINS or bd & GLOBAL_CONFLICT_DOMAINS:
        return bool(ad & bd)
    return bool(set(a.resource_claims) & set(b.resource_claims))


def can_shadow_parallel(a: SchedulingMeta, b: SchedulingMeta) -> bool:
    if claims_conflict(a, b):
        return False
    # READ_ONLY jobs with disjoint resources may run in parallel.
    if a.mode == "READ_ONLY" and b.mode == "READ_ONLY":
        return True
    # Mutations may only be considered parallel when they explicitly declare
    # non-overlapping resources and are not legacy-conservative jobs.
    if a.legacy_defaults or b.legacy_defaults:
        return False
    if not a.resource_claims or not b.resource_claims:
        return False
    return True


def load_envelopes(folder: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    if not folder.is_dir():
        return rows
    for path in sorted(folder.glob("*.json")):
        try:
            doc = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        job = doc.get("job") if isinstance(doc, dict) and isinstance(doc.get("job"), dict) else doc
        if not isinstance(job, dict):
            continue
        rows.append({"path": str(path), "job": job, "meta": normalize_metadata(job)})
    return rows


def fairness_key(row: dict[str, Any], served: dict[str, int] | None = None) -> tuple[Any, ...]:
    served = served or {}
    meta: SchedulingMeta = row["meta"]
    project_served = int(served.get(meta.project_id, 0))
    # Lower is better. Weighted service count gives projects with larger
    # fairness_weight proportionally more opportunities without starvation.
    normalized_service = project_served / max(meta.fairness_weight, 1)
    job_id = str(row["job"].get("job_id") or "")
    return (PRIORITY_ORDER[meta.priority_class], normalized_service, meta.project_id, job_id)


def choose_shadow_slots(
    pending: list[dict[str, Any]],
    active: list[dict[str, Any]],
    *,
    max_slots: int = 4,
    served: dict[str, int] | None = None,
) -> list[dict[str, Any]]:
    selected: list[dict[str, Any]] = []
    project_counts: dict[str, int] = {}
    ordered = sorted(pending, key=lambda row: fairness_key(row, served))

    active_meta = [row["meta"] for row in active]
    for row in ordered:
        if len(selected) >= max_slots:
            break
        meta: SchedulingMeta = row["meta"]
        current = project_counts.get(meta.project_id, 0)
        if current >= meta.max_parallelism:
            continue
        blockers = active_meta + [item["meta"] for item in selected]
        if any(not can_shadow_parallel(meta, other) for other in blockers):
            continue
        selected.append(row)
        project_counts[meta.project_id] = current + 1
    return selected


def decision_payload(max_slots: int = 4) -> dict[str, Any]:
    pending = load_envelopes(PENDING)
    active = load_envelopes(PROCESSING)
    selected = choose_shadow_slots(pending, active, max_slots=max_slots)
    return {
        "schema": "edarsahub.worker-shadow-scheduler.v1",
        "mode": "SHADOW_ONLY",
        "authoritative_executor": "edarsahub-universal-worker",
        "max_slots_simulated": max_slots,
        "pending_count": len(pending),
        "active_count": len(active),
        "selected": [
            {
                "job_id": row["job"].get("job_id"),
                "project_id": row["meta"].project_id,
                "bounded_context": row["meta"].bounded_context,
                "priority_class": row["meta"].priority_class,
                "resource_claims": list(row["meta"].resource_claims),
                "conflict_domains": list(row["meta"].conflict_domains),
                "legacy_defaults": row["meta"].legacy_defaults,
            }
            for row in selected
        ],
        "executed_jobs": [],
        "queue_mutations": 0,
        "production_touched": False,
    }


def main() -> int:
    print(json.dumps(decision_payload(), ensure_ascii=False, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

from importlib.util import module_from_spec, spec_from_file_location
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
MODULE = ROOT / "tools" / "mirror_sync" / "multiproject_shadow_scheduler.py"

spec = spec_from_file_location("multiproject_shadow_scheduler", MODULE)
mod = module_from_spec(spec)
assert spec and spec.loader
spec.loader.exec_module(mod)


def row(job):
    return {"job": job, "meta": mod.normalize_metadata(job)}


def test_legacy_jobs_are_conservative_and_global():
    meta = mod.normalize_metadata({"job_id": "OLD", "mode": "READ_ONLY"})
    assert meta.project_id == "LEGACY_GLOBAL"
    assert meta.conflict_domains == ("GLOBAL_GIT_WRITER",)
    assert meta.legacy_defaults is True


def test_disjoint_readonly_projects_can_shadow_parallel():
    a = mod.normalize_metadata({
        "mode": "READ_ONLY",
        "scheduling": {
            "project_id": "CAVAS",
            "bounded_context": "cavas",
            "resource_claims": ["backend/modules/cava_socios"],
            "conflict_domains": ["CAVAS"],
        },
    })
    b = mod.normalize_metadata({
        "mode": "READ_ONLY",
        "scheduling": {
            "project_id": "TABLAJERIAS",
            "bounded_context": "tablajerias",
            "resource_claims": ["backend/modules/tablajeria"],
            "conflict_domains": ["TABLAJERIAS"],
        },
    })
    assert mod.can_shadow_parallel(a, b) is True


def test_same_resource_blocks_parallelism():
    common = ["frontend/src/App.js"]
    a = mod.normalize_metadata({"mode": "MUTATION", "scheduling": {
        "project_id": "CAVAS", "resource_claims": common, "conflict_domains": ["CAVAS"]}})
    b = mod.normalize_metadata({"mode": "MUTATION", "scheduling": {
        "project_id": "TABLAJERIAS", "resource_claims": common, "conflict_domains": ["TABLAJERIAS"]}})
    assert mod.can_shadow_parallel(a, b) is False


def test_global_domain_serializes():
    a = mod.normalize_metadata({"mode": "READ_ONLY", "scheduling": {
        "project_id": "A", "conflict_domains": ["GLOBAL_NAVIGATION"]}})
    b = mod.normalize_metadata({"mode": "READ_ONLY", "scheduling": {
        "project_id": "B", "conflict_domains": ["GLOBAL_NAVIGATION"]}})
    assert mod.can_shadow_parallel(a, b) is False


def test_project_max_parallelism_is_respected():
    pending = [
        row({"job_id": "A1", "mode": "READ_ONLY", "scheduling": {
            "project_id": "A", "resource_claims": ["a1"], "conflict_domains": ["A1"], "max_parallelism": 1}}),
        row({"job_id": "A2", "mode": "READ_ONLY", "scheduling": {
            "project_id": "A", "resource_claims": ["a2"], "conflict_domains": ["A2"], "max_parallelism": 1}}),
    ]
    selected = mod.choose_shadow_slots(pending, [], max_slots=4)
    assert len(selected) == 1


def test_weighted_fairness_changes_order_without_starvation():
    a = row({"job_id": "A", "mode": "READ_ONLY", "scheduling": {
        "project_id": "A", "fairness_weight": 1, "resource_claims": ["a"], "conflict_domains": ["A"]}})
    b = row({"job_id": "B", "mode": "READ_ONLY", "scheduling": {
        "project_id": "B", "fairness_weight": 4, "resource_claims": ["b"], "conflict_domains": ["B"]}})
    ordered = sorted([a, b], key=lambda r: mod.fairness_key(r, {"A": 2, "B": 2}))
    assert ordered[0]["meta"].project_id == "B"


def test_shadow_payload_never_executes_or_mutates():
    payload = mod.decision_payload(max_slots=2)
    assert payload["mode"] == "SHADOW_ONLY"
    assert payload["authoritative_executor"] == "edarsahub-universal-worker"
    assert payload["executed_jobs"] == []
    assert payload["queue_mutations"] == 0
    assert payload["production_touched"] is False
